      const f = Math.min(1, Math.max(0, (at - C[i]) / len)), ux = (B.x - A.x) / len, uz = (B.z - A.z) / len;
      const sd = zr() < 0.5 ? 1 : -1, al = (zr() - 0.5) * 0.8, up = zr() * 0.1, off = (zr() - 0.5) * 3;   // 起點散在路線兩側 1.5 格內
