    DIA(M, 'head', [0.188, 0.932, 0.2525], [1, -0.15, 0], 0.06, 0.018, [0, 0, 1], 0.008, 'hair');
    /* ── 領口：只留一圈平的，把身體頂（0.69）接到頭底（0.74）。比頭小，遊戲鏡頭從上面看幾乎都被頭擋住；拉鍊拉到頂。
       v1.258.0 之前是兩層往外翻的高領（四角切斜角、正面開一道小口），使用者：「領子現在這樣也不好看 或許可以細節簡化 不要高領了」 ── */
